/* All default examples are synthetic teaching material. No personal research is distributed. */
(function (root) {
  'use strict';
  const C = root.CampusPPT;
  const chartData = '';
  const source = { kind: 'synthetic', title: '合成教学示例，仅用于演示页面组织与读图', venue: '求是·汇报', year: '', url: '', status: '' };
  const image = () => ({ dataUrl: 'data:image/png;base64,' + chartData, width: 1185, height: 704, alt: '合成教学折线图，练习 A 在三轮读数为 8、12、14，练习 B 为 10、11、13。' });
  const slide = (id, type, section, title, more) => ({ id, type, section, title, subtitle: '', body: [], columns: [], image: null,
    caption: '', citations: [], notes: '', evidence: 'teaching', durationSec: type === 'cover' ? 25 : 60, ...more });

  function createDemo(scene) {
    const key = Object.hasOwn(C.sceneTemplates, scene) ? scene : 'course';
    let title, subtitle, slides;
    if (key === 'course') {
      title = '研究问题与证据组织'; subtitle = '课程汇报示例';
      slides = [
        slide('course-cover', 'cover', '问题导入', title, { subtitle: '在一次课堂练习中，区分观察、解释与结论', notes: '本套内容是合成教学示例。介绍课程任务：围绕一个问题，说明证据能回答什么、还缺少什么。' }),
        slide('course-section', 'section', '问题导入', '一张比较图能够回答什么', { subtitle: '本节关注图中信息与结论范围的对应关系', notes: '请同学先说出自己在图中会查看哪些信息。收集两到三个回答，再进入概念页。' }),
        slide('course-concept', 'bullets', '概念理解', '观察与解释的层次', { body: ['观察：准确描述对象、条件与读数变化。', '解释：提出能够说明观察结果的理由。', '结论：明确证据支持的范围，并保留尚未解决的问题。'], notes: '可让同学用一句话分别说出观察和解释。追问：还需要哪些证据，才能把一种解释作为结论？', citations: [source] }),
        slide('course-compare', 'comparison', '概念理解', '两种表述的证据要求', { columns: [
          { title: '描述图中差异', body: ['说明比较对象与时间点。', '保留坐标、单位及图例。', '指出图中能直接读到的变化。'] },
          { title: '解释差异原因', body: ['说明分组方式和潜在影响因素。', '结合独立证据判断解释是否成立。', '明确现有设计无法回答的部分。'] }
        ], notes: '用两栏对照“看到什么”和“为什么发生”。提醒同学：表述越接近原因解释，需要交代的研究设计越完整。', citations: [source] }),
        slide('course-figure', 'figure', '应用练习', '合成数据的读图练习', { image: image(), caption: '两组读数来自预设的课堂练习数据，不代表真实教学或研究结果。', body: ['先说明横轴、纵轴和两条曲线。', '找出第 2 次练习的读数差异。', '讨论：图中没有提供哪些必要信息？'], notes: '图中练习 A 的读数为 8、12、14，练习 B 为 10、11、13。第 2 次差值为 1。数据完全合成，不用于评价真实教学效果。', citations: [source] }),
        slide('course-summary', 'bullets', '学习小结', '课堂检查与课后任务', { body: ['用一句话概括这张图中的可见现象。', '列出支持原因解释还需要补充的信息。', '选择自己课程中的一张图，按相同顺序准备 1 分钟讲解。'], notes: '课堂检查以学生回答为依据。课后任务要求附来源，并明确图区分描述性观察与原因解释。', citations: [source] })
      ];
    } else if (key === 'lab') {
      title = '组会汇报中的问题与证据'; subtitle = '研究进展组织示例';
      slides = [
        slide('lab-cover', 'cover', '研究问题', title, { subtitle: '将已知依据、当前进展与下一步安排分别说明', notes: '本演示使用合成内容，不对应个人课题，也不包含真实科研结论。' }),
        slide('lab-section', 'section', '研究问题', '本次组会需要讨论的选择', { subtitle: '围绕一个明确问题组织材料', notes: '本节先说明本次讨论希望解决的选择，避免按文件或操作的先后顺序堆叠材料。' }),
        slide('lab-question', 'bullets', '方法与进展', '方法与进展的呈现顺序', { body: ['交代研究对象、比较条件和具体读出。', '说明本次已经完成的操作及其证据。', '把尚未完成的分析与实验列入下一步计划。'], notes: '根据实际材料填写，不因版面留空而补写数字或实验结果。这里呈现的是汇报方法的教学示例。', citations: [source] }),
        slide('lab-compare', 'comparison', '结果与解释', '结果与下一步安排分别表述', { columns: [
          { title: '已有证据', body: ['说明本次观察及其适用条件。', '交代样本或重复单位。', '保留会影响解释的限制。'] },
          { title: '拟开展工作', body: ['说明待验证的问题。', '列出需要补充的比较。', '明确计划完成后能够判断什么。'] }
        ], notes: '如果使用公开数据再分析，给出数据来源与自己的分析范围。计划不得写成已完成结果。', citations: [source] }),
        slide('lab-figure', 'figure', '结果与解释', '结果图与判断的对应', { image: image(), body: ['一句图注概括本页所展示的信息。', '读图顺序与关键数值放入备注。', '影响结论的限制仍保留在正文。'], caption: '图为合成教学数据，演示原图按比例展示与说明文字的配对。', notes: '本图不是课题结果。读图时依次说明坐标、分组与差异。数据为练习 A：8、12、14，练习 B：10、11、13。', citations: [source] }),
        slide('lab-next', 'bullets', '下一步计划', '下一步工作与讨论问题', { evidence: 'plan', body: ['补齐真实材料对应的来源与实验条件。', '确认优先处理的问题及其所需证据。', '在下次组会报告新证据是否改变当前判断。'], notes: '请根据实际课题填写具体行动、时间安排与需要导师协助判断的选择。这里仅展示计划页结构。', citations: [source] })
      ];
    } else {
      title = '文献分享中的证据链'; subtitle = '批判性阅读组织示例';
      slides = [
        slide('journal-cover', 'cover', '论文与问题', title, { subtitle: '从研究问题、实验设计到结论范围', notes: '本套内容演示文献分享的组织方法，不代替对任何具体论文的精读。' }),
        slide('journal-section', 'section', '论文与问题', '论文试图回答的具体问题', { subtitle: '以作者提出的问题组织阅读顺序', notes: '真实汇报时补充论文完整题名、期刊、年份与链接。先说明论文问题，再解释为什么选择这篇论文。' }),
        slide('journal-design', 'bullets', '研究设计', '研究设计与证据位置', { body: ['明确对象、研究体系与主要比较。', '将主要结论对应到实验或数据图。', '记录原始数据、补充材料和代码的可获取情况。'], notes: '判断哪些证据已经直接阅读，哪些仅见于摘要或二手说明。实际汇报应补充与结论相关的方法细节。', citations: [source] }),
        slide('journal-compare', 'comparison', '核心证据', '作者结果与汇报者推断', { columns: [
          { title: '作者报告的结果', body: ['按原文说明操作与读出。', '保持实验条件和比较范围。', '用原图及完整来源支持表述。'] },
          { title: '可以进一步讨论的问题', body: ['指出研究尚未回答的部分。', '说明新解释需要哪些证据。', '标明跨体系迁移的假设。'] }
        ], notes: '两栏用于防止把自己的延伸想法写成论文已经证明的结论。实际内容必须根据原文填写。', citations: [source] }),
        slide('journal-figure', 'figure', '核心证据', '图、图注与来源共同呈现', { image: image(), body: ['按比例保留图中信息。', '用短图注说明读图重点。', '详细图号与页码记录在备注。'], caption: '此图使用合成教学数据，演示图文页结构，不属于任何已发表论文。', notes: '正式分享时使用允许展示的论文原图。核对作者结论与图中读出是否一致，不将示例图当成真实论文证据。', citations: [source] }),
        slide('journal-close', 'bullets', '讨论与启发', '讨论与可复用材料', { body: ['论文问题与证据之间是否存在缺口？', '哪些材料可以公开获取和进一步分析？', '对自己的研究最具体的启发是什么？'], notes: '启发应落到可验证问题或具体方法。下载条件、材料层级及访问限制依真实来源记录。', citations: [source] })
      ];
    }
    return C.normalizeProject({ version: 1, title, subtitle, presenter: '教学演示', scene: key, duration: 8,
      theme: { palette: 'zju-blue', accent: '#074591', font: '华文楷体', nav: 'top' }, slides });
  }
  C.createDemo = createDemo;
})(typeof window !== 'undefined' ? window : globalThis);
